from dataclasses import dataclass
from typing import List, Tuple


@dataclass
class Student:
    name: str
    age: int
    score: float


class StudentRoster:
    def __init__(self):
        self.students: List[Student] = []

    def add(self, name: str, age: int, score: float) -> None:
        self.students.append(Student(name, age, score))

    def average_score(self) -> float:
        if not self.students:
            return 0.0
        return sum(student.score for student in self.students) / len(self.students)

    def top_students(self, n: int) -> List[Tuple[str, int, float]]:
        sorted_students = sorted(self.students, key=lambda s: s.score, reverse=True)
        return [(s.name, s.age, s.score) for s in sorted_students[:n]]
